def bubble_sort(items):
    items = items[:]                      # work on a copy
    for end in range(len(items) - 1, 0, -1):
        swapped = False
        for i in range(end):
            if items[i] > items[i + 1]:
                items[i], items[i + 1] = items[i + 1], items[i]
                swapped = True
        print("pass:", items)
        if not swapped:                   # already sorted: stop early
            break
    return items

print(bubble_sort([5, 2, 4, 1]))

