import sys

def count_down(n):
    if n == 0:
        return "done"
    return count_down(n - 1)

print("limit:", sys.getrecursionlimit())
print(count_down(500))

try:
    count_down(5000)
except RecursionError:
    print("5000 deep: RecursionError, so use a loop instead")

